float2 hor = float2 (texsize.z,0);
float2 ver = float2 (0, texsize.w);
float dx = lum(GetPixel(uv3+hor) - GetPixel(uv3-hor));
float dy = lum(GetPixel(uv3+ver) - GetPixel(uv3-ver));
float2 dz = float2 (dx,dy);
//dz *= (length(dz) >= .01);
uv3 += dz * (1-mask);
//Strahl
uv4 = float2(.5,uv1.x/uv1.y);
uv4 = frac(.06*bass_att*uv4);
float3 col = 1;
float3 ret3 = GetPixel(uv4*14);
ret3 += (.008/(length(uv1)))*col;
//ret2 *= q10;
float3 mus = .02 / (length(uv1+.45+dz*16));
float mus2 = saturate(.01*abs(uv3.x-.5)/abs(uv3.y-.55)-dz*4);
float stars = saturate(1/((uv.x*3234224*uv.y)%22345));
ret1 = GetPixel(frac(uv3));
ret1 *= 1-mask/2;;
float fmask = saturate (1-lum(ret1*4));
